/// Where a daily-rebalanced inverse fund ends up over a PATH, against where a naive reading expects.
///
/// A `-3x` fund does not deliver `-3 ×` the period return over more than one day, and the gap is not
/// a fee — it is compounding. Up 10% then down 9.09% leaves the index flat and a 3x inverse fund
/// down about 11%. Over a choppy year this is the dominant term, and it is why these are built for
/// single-day holds.
pub fn inverse_drift(daily_returns: &[f64], multiple: f64) -> (f64, f64) {
    let index = daily_returns.iter().fold(1.0, |v, r| v * (1.0 + r)) - 1.0;
    let fund = daily_returns.iter().fold(1.0, |v, r| v * (1.0 + multiple * -r)) - 1.0;
    // What somebody reading the label expects, and what compounding actually produced.
    (-multiple * index, fund)
}
